From 085bc0e576a4bf53b67a917c54908f299a2fb949 Mon Sep 17 00:00:00 2001
From: Tony Lindgren <tony@atomide.com>
Date: Sun, 31 May 2020 12:37:54 -0700
Subject: [PATCH] bus: ti-sysc: Fix uninitialized framedonetv_irq

We are currently only setting the framedonetv_irq disabled for the SoCs
that don't have it. But we are never setting it enabled for the SoCs that
have it. Let's initialized it to true by default.

Fixes: 7324a7a0d5e2 ("bus: ti-sysc: Implement display subsystem reset quirk")
Cc: Laurent Pinchart <laurent.pinchart@ideasonboard.com>
Cc: Tomi Valkeinen <tomi.valkeinen@ti.com>
Signed-off-by: Tony Lindgren <tony@atomide.com>

diff --git a/drivers/bus/ti-sysc.c b/drivers/bus/ti-sysc.c
index 4f640a635ded..db9541f38505 100644
--- a/drivers/bus/ti-sysc.c
+++ b/drivers/bus/ti-sysc.c
@@ -1552,7 +1552,7 @@ static u32 sysc_quirk_dispc(struct sysc *ddata, int dispc_offset,
 	bool lcd_en, digit_en, lcd2_en = false, lcd3_en = false;
 	const int lcd_en_mask = BIT(0), digit_en_mask = BIT(1);
 	int manager_count;
-	bool framedonetv_irq;
+	bool framedonetv_irq = true;
 	u32 val, irq_mask = 0;

 	switch (sysc_soc->soc) {
@@ -1569,6 +1569,7 @@ static u32 sysc_quirk_dispc(struct sysc *ddata, int dispc_offset,
 		break;
 	case SOC_AM4:
 		manager_count = 1;
+		framedonetv_irq = false;
 		break;
 	case SOC_UNKNOWN:
 	default:
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `framedonetv_irq` variable being uninitialized, which could lead to unpredictable behavior when the variable is used in the code. This oversight meant that for SoCs that have the `framedonetv_irq`, it was not being set to a known state, potentially causing issues in the display subsystem reset functionality.

        Commit message:
        bus: ti-sysc: Fix uninitialized framedonetv_irq

We are currently only setting the framedonetv_irq disabled for the SoCs
that don't have it. But we are never setting it enabled for the SoCs that
have it. Let's initialized it to true by default.

Fixes: 7324a7a0d5e2 ("bus: ti-sysc: Implement display subsystem reset quirk")
Cc: Laurent Pinchart <laurent.pinchart@ideasonboard.com>
Cc: Tomi Valkeinen <tomi.valkeinen@ti.com>
Signed-off-by: Tony Lindgren <tony@atomide.com>  

        Patch:
          */
 static u32 sysc_quirk_dispc(struct sysc *ddata, int dispc_offset,
 			    bool disable)
 {
 	bool lcd_en, digit_en, lcd2_en = false, lcd3_en = false;
 	const int lcd_en_mask = BIT(0), digit_en_mask = BIT(1);
 	int manager_count;
-	bool framedonetv_irq;
+	bool framedonetv_irq = true;
 	u32 val, irq_mask = 0;

 	switch (sysc_soc->soc) {
 	case SOC_2420 ... SOC_3630:
 		manager_count = 2;
 		framedonetv_irq = false;
 		break;
 	case SOC_4430 ... SOC_4470:
 		manager_count = 3;
 		break;
 	case SOC_5430:
 	case SOC_DRA7:
 		manager_count = 4;
 		break;
 	case SOC_AM4:
 		manager_count = 1;
+		framedonetv_irq = false;
 		break;
 	case SOC_UNKNOWN:
 	default:
 		return 0;
 	};

 	/* Remap the whole module range to be able to reset dispc outputs */
 	devm_iounmap(ddata->dev, ddata->module_va);
 	ddata->module_va = devm_ioremap(ddata->dev,
 					ddata->module_pa,
 					ddata->module_size);
 	if (!ddata->module_va)
 		return -EIO;

 	/* DISP_CONTROL */
 	val = sysc_read(ddata, dispc_offset + 0x40);
 	lcd_en = val & lcd_en_mask;
 	digit_en = val & digit_en_mask;
 	if (lcd_en)
 		irq_mask |= BIT(0);			/* FRAMEDONE */
 	if (digit_en) {
 		if (framedonetv_irq)
 			irq_mask |= BIT(24);		/* FRAMEDONETV */
 		else
 			irq_mask |= BIT(2) | BIT(3);	/* EVSYNC bits */
 	}
 	if (disable & (lcd_en | digit_en))
 		sysc_write(ddata, dispc_offset + 0x40,
 			   val & ~(lcd_en_mask | digit_en_mask));

 	if (manager_count <= 2)
 		return irq_mask;

 	/* DISPC_CONTROL2 */
 	val = sysc_read(ddata, dispc_offset + 0x238);
 	lcd2_en = val & lcd_en_mask;
 	if (lcd2_en)
 		irq_mask |= BIT(22);			/* FRAMEDONE2 */
 	if (disable && lcd2_en)
 		sysc_write(ddata, dispc_offset + 0x238,
 			   val & ~lcd_en_mask);

 	if (manager_count <= 3)
 		return irq_mask;

 	/* DISPC_CONTROL3 */
 	val = sysc_read(ddata, dispc_offset + 0x848);
 	lcd3_en = val & lcd_en_mask;
 	if (lcd3_en)
 		irq_mask |= BIT(30);			/* FRAMEDONE3 */
 	if (disable && lcd3_en)
 		sysc_write(ddata, dispc_offset + 0x848,
 			   val & ~lcd_en_mask);

 	return irq_mask;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
- bool framedonetv_irq;
- +	bool framedonetv_irq = true;
- framedonetv_irq = false;
- +		framedonetv_irq = false;

Code statements:
- bool framedonetv_irq;
- framedonetv_irq = true;
- framedonetv_irq = false;
